export const FILE_PAGE_SIZE=40;
export const fileNameCollator=new Intl.Collator(undefined,{numeric:true,sensitivity:'base'});

// Keep the DOM (including thumbnail observers) bounded without dropping any
// search results. A new filter/folder starts at the first page immediately.
export function usePagedRows<T>(rows:T[],resetKey:string,pageSize=FILE_PAGE_SIZE){
  const [selection,setSelection]=useState({key:resetKey,page:0});
  const pageCount=Math.max(1,Math.ceil(rows.length/pageSize));
  const page=selection.key===resetKey?Math.min(selection.page,pageCount-1):0;
  const setPage=(next:number)=>setSelection({key:resetKey,page:Math.max(0,Math.min(next,pageCount-1))});
  return{page,pageSize,setPage,rows:rows.slice(page*pageSize,(page+1)*pageSize)};
}

export function ListPagination({count,page,pageSize=FILE_PAGE_SIZE,onPageChange,label='Страницы файлов'}:{count:number;page:number;pageSize?:number;onPageChange:(page:number)=>void;label?:string}){
  if(count<=pageSize)return null;
  const pages=Math.ceil(count/pageSize);
  return <nav className={styles.pagination} aria-label={label}>
    <span>{page*pageSize+1}–{Math.min(count,(page+1)*pageSize)} из {count}</span>
    <button type="button" disabled={page===0} onClick={()=>onPageChange(page-1)}>Назад</button>
    <strong>{page+1} / {pages}</strong>
    <button type="button" disabled={page>=pages-1} onClick={()=>onPageChange(page+1)}>Далее</button>
  </nav>;
}

