        <div className="localFileInfo"><b title={entry.path}>{leafName(entry.path)}</b>{(query||parentPath(entry.path)!==folder)&&<small title={entry.path}>{parentPath(entry.path)||'Моя флешка'}</small>}<div><span><Database/>{bytes(entry.size)}</span><span><Clock3/>{date(entry.modified)}</span></div></div>
        <div className="localFileActions"><button type="button" className="primary" disabled={!canPrint||busy} title={canPrint?'Полная проверка и запуск':'Нужен готовый принтер в локальной сети'} onClick={()=>prepare(entry,'start')}><Play/>Печать</button><button type="button" disabled={!canQueue||busy} title={canQueue?'Полная проверка и добавление в очередь':'Нужна локальная связь с Moonraker'} onClick={()=>prepare(entry,'queue')}><ListPlus/>В очередь</button><button type="button" className="danger" disabled={!canOperate||busy} title="Удалить из локальной библиотеки" onClick={()=>setAction({kind:'delete',entry})}><Trash2/></button></div>
      </article>})}
      {!busy&&!folderRows.length&&!visibleFiles.length&&<div className="printerFilesEmpty"><HardDrive/><b>{entries.length?'Ничего не найдено':'Локальная флешка пока пустая'}</b><span>{entries.length?'Измените запрос или вернитесь в корневую папку.':'Нажмите «Добавить файл» для одного G-code или «Выбрать папку» для всей флешки.'}</span></div>}
      {busy&&!entries.length&&!importProgress&&<div className="printerFilesEmpty loading"><RefreshCw className="spin"/><b>Открываем локальную библиотеку…</b><span>Интернет для этого не нужен.</span></div>}
    </div>
    <ListPagination count={browserRows.length} page={browserPage.page} onPageChange={page=>{browserPage.setPage(page);libraryRef.current?.scrollTo({top:0})}} label="Страницы локальной библиотеки"/>

    {action&&<div className="printerFileDialogBackdrop" onMouseDown={event=>{if(event.target===event.currentTarget&&!busy)setAction(undefined)}}>
      <section className={`printerFileDialog ${action.kind}`} role="dialog" aria-modal="true" aria-labelledby="local-library-dialog-title">
        <header><i>{action.kind==='start'?<Play/>:action.kind==='queue'?<ListPlus/>:<ShieldAlert/>}</i><span><small>{action.kind==='delete'?'LOCAL STORAGE':'G-CODE PREFLIGHT'}</small><b id="local-library-dialog-title">{launchUnconfirmed?'Запуск не подтверждён':error&&(action.kind==='start'||action.kind==='queue')?'Отправка не завершена':action.kind==='start'?'Проверка G-code пройдена':action.kind==='queue'?'Проверка G-code пройдена':action.kind==='delete'?'Удалить файл из «Моей флешки»?':'Запуск заблокирован'}</b><em>{action.entry.path}</em></span><button type="button" disabled={busy} onClick={()=>setAction(undefined)}><X/></button></header>
        {action.kind==='delete'?<p>Удалится только эта локальная копия. Файлы на физической флешке и на принтерах не изменятся.</p>:<div className="printerFileIssueList">{action.report?.issues.map(issue=><div className={issue.level} key={`${issue.code}:${issue.message}`}><i>{issue.level==='error'?<ShieldAlert/>:<CheckCircle2/>}</i><span>{issue.message}</span></div>)}</div>}
        {error&&<div className="printerFileOperationError" role="alert"><ShieldAlert/><span>{error}</span></div>}
        {transfer&&<LocalTransferStatus transfer={transfer} launching={launching} cancelRequested={cancelRequested} queue={action.kind==='queue'} cancel={cancelTransfer}/> }
        <footer><button type="button" disabled={busy} onClick={()=>{setAction(undefined);setError('');setLaunchUnconfirmed(false)}}>{launchUnconfirmed?'Закрыть':'Отмена'}</button>{action.kind!=='blocked' &&<button type="button" className={action.kind==='delete'?'danger':'primary'} disabled={busy||launchUnconfirmed} onClick={confirmAction}>{busy?<RefreshCw className="spin"/>:action.kind==='start'?<Play/>:action.kind==='queue'?<ListPlus/>:<Trash2/>}{busy?(action.kind==='delete'?'Удаление…':launching?'Подтверждаем команду…':'Передача файла…'):action.kind==='start'?`Отправить и запустить на ${printerDisplayName(printer)}`:action.kind==='queue'?`Отправить в очередь ${printerDisplayName(printer)}`:'Удалить локальную копию'}</button>}{action.kind==='blocked'&&<button type="button" className="primary" onClick={()=>setAction(undefined)}>Понятно</button>}</footer>
      </section>
    </div>}

    {folderDelete&&<div className="printerFileDialogBackdrop" onMouseDown={event=>{if(event.target===event.currentTarget&&!busy)setFolderDelete(undefined)}}>
      <section className="printerFileDialog delete" role="dialog" aria-modal="true" aria-labelledby="local-folder-delete-title">
        <header><i><Trash2/></i><span><small>LOCAL STORAGE · ПАПКА</small><b id="local-folder-delete-title">Удалить папку из «Моей флешки»?</b><em>{folderDelete.path}</em></span><button type="button" disabled={busy} onClick={()=>setFolderDelete(undefined)} aria-label="Закрыть окно"><X/></button></header>
        <p>Будет удалена папка «{folderDelete.name}» и вложенные G-code — {folderDelete.files} {filesLabel(folderDelete.files)} ({bytes(folderDelete.size)}) — из библиотеки <b>{libraryScopeLabel}</b>. {librarySharedByModel?'Папка исчезнет у всех принтеров этой модели. ':''}Физическая USB-флешка, библиотеки других моделей и файлы в Moonraker не изменятся.</p>
        <footer><button type="button" disabled={busy} onClick={()=>setFolderDelete(undefined)}>Отмена</button><button type="button" className="danger" disabled={busy||!canOperate} onClick={confirmFolderDelete}>{busy?<RefreshCw className="spin"/>:<Trash2/>}Удалить папку и файлы</button></footer>
      </section>
    </div>}
  </div>;
}

import { useCallback, useEffect, useMemo, useRef, useState, type DragEvent } from 'react';
import {
  Activity,
  CheckCircle2,
  Clock3,
