/** Keep an authenticated monitoring document eligible for background work.
 * This is an origin-scoped Web Lock, not an OS/display wake lock. It is released
 * when monitoring stops; native printer actors remain responsible for polling.
 */
export function holdMonitoringActivity(onError:(reason:unknown)=>void=()=>{}){
  const locks=navigator.locks;
  if(!locks)return()=>{};
  const abort=new AbortController();
  let stopped=false,release:(()=>void)|undefined;
  const lifetime=new Promise<void>(resolve=>{release=resolve});
  try{
    void locks.request('klipper-farm.monitoring',{mode:'shared',signal:abort.signal},async()=>{
      if(!stopped)await lifetime;
    }).catch(reason=>{if(!stopped)onError(reason)});
  }catch(reason){onError(reason)}
  return()=>{stopped=true;release?.();abort.abort()};
}

/** Video rendering callbacks can stop for an occluded/minimized WebView.
 * Receiver decoder counters still describe the live stream without relying on
 * the compositor. A counter advance is necessary; pixels are validated by the
 * caller as well, so new packets containing an unchanged image are not evidence.
 */
export class CameraVideoProgress {
  private previous=new Map<string,number>();
  private sampledAt:number|undefined;
  sample(report:RTCStatsReport,now:number):string|undefined {
    const next=new Map<string,number>();
    report.forEach(row=>{
      if(row.type!=='inbound-rtp'||(row.kind??row.mediaType)!=='video'||!Number.isFinite(row.framesDecoded)||row.framesDecoded<0)return;
      next.set(row.id,row.framesDecoded);
    });
    const contiguous=this.sampledAt!==undefined&&now>=this.sampledAt&&now-this.sampledAt<=15_000;
    const advanced=contiguous&&[...next].some(([id,count])=>this.previous.has(id)&&count>this.previous.get(id)!);
    this.previous=next;this.sampledAt=now;
    return advanced?[...next].sort(([a],[b])=>a.localeCompare(b)).map(([id,count])=>`${id}:${count}`).join('|'):undefined;
  }
}

type Options={
  peer:RTCPeerConnection;
  video:HTMLVideoElement;
  intervalMs:number;
  getJobToken:()=>string|undefined;
  capture:(token:string,capturedAt:number,jobToken:string)=>Promise<void>;
  unavailable:(reason:string)=>void;
  progressed:()=>void;
};

/** Runs one low-rate, non-overlapping sampler even when no video is painted.
 * After a suspended timer gap it first establishes a new decoder baseline.
 */
export function sampleCameraVideo({peer,video,intervalMs,getJobToken,capture,unavailable,progressed}:Options){
  const progress=new CameraVideoProgress();
  let stopped=false,timer:ReturnType<typeof setTimeout>|undefined;
  const tick=async()=>{
    try{
      const report=await peer.getStats();
      if(stopped)return;
      const at=Date.now(),token=progress.sample(report,at),jobToken=getJobToken();
      const drawable=video.readyState>=2&&video.videoWidth>0&&video.videoHeight>0;
      // A decoder counter cannot heal a video element that never acquired a
      // drawable frame. Repeated/dark pixels, however, are an unavailable
      // observation rather than a reason to reconnect a healthy transport.
      if(token&&drawable)progressed();
      if(jobToken&&drawable){
        if(token)await capture(token,at,jobToken);
        else unavailable('Ждём новый декодированный видеокадр');
      }
    }catch(reason){if(!stopped)unavailable(String(reason instanceof Error?reason.message:reason).slice(0,200))}
    finally{if(!stopped)timer=setTimeout(()=>void tick(),intervalMs)}
  };
  void tick();
  return()=>{stopped=true;if(timer!==undefined)clearTimeout(timer)};
}

